import { getAllProducts } from '@/lib/db';
import { revalidateTag } from 'next/cache';

// Cached function to fetch products with "products" cache tag
async function getCachedProducts() {
  'use cache';

  const products = await getAllProducts();
  return products;
}

// Configure cache options with tag
getCachedProducts.cacheTag = 'products';

// Child component that fetches and displays products
async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div style={{ marginTop: '20px' }}>
      <h2>Product Listing</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: '10px',
              margin: '5px 0',
              border: '1px solid #ddd',
              borderRadius: '4px'
            }}
          >
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
      <p style={{ fontSize: '12px', color: '#666', marginTop: '10px' }}>
        Last fetched: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

// Form component with inline server action for cache invalidation
function InvalidateForm() {
  async function invalidateProductsCache() {
    'use server';

    // Invalidate the "products" cache tag
    revalidateTag('products');
    console.log('Products cache invalidated at:', new Date().toISOString());
  }

  return (
    <form action={invalidateProductsCache} style={{ marginTop: '20px' }}>
      <button
        type="submit"
        style={{
          padding: '10px 20px',
          backgroundColor: '#0070f3',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        Invalidate Products Cache
      </button>
      <p style={{ fontSize: '12px', color: '#666', marginTop: '10px' }}>
        Click to force refresh product data on next render
      </p>
    </form>
  );
}

export default function Page() {
  return (
    <div style={{ padding: '20px', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Home</h1>

      <div style={{
        backgroundColor: '#f5f5f5',
        padding: '15px',
        borderRadius: '8px',
        marginTop: '20px'
      }}>
        <h3>Cache Invalidation Demo</h3>
        <p style={{ fontSize: '14px' }}>
          This demo shows efficient data caching with selective invalidation:
        </p>
        <ul style={{ fontSize: '14px' }}>
          <li>Product data is cached with the "products" tag</li>
          <li>Initial loads are instant (served from cache)</li>
          <li>Cache invalidation updates only product data</li>
          <li>Other cached data remains unaffected</li>
        </ul>
      </div>

      <ProductList />
      <InvalidateForm />
    </div>
  );
}

